// Extract user profile for regulation scanning
const body = $input.item.json.body;
const industry = body.industry || 'Contractor';
const location = body.location || 'New York, NY';
const email = body.email || 'user@example.com';

// Simulate dynamic public source queries based on profile
let regulations = [];

if (industry.toLowerCase().includes('contractor') && location.toLowerCase().includes('new york')) {
  regulations.push({
    title: 'NYC Department of Buildings Contractor Permit Renewal',
    deadlineDays: 30,
    plainEnglish: 'Renew your NYC contractor license or face fines up to $500.',
    sourceUrl: 'https://www1.nyc.gov/site/buildings/index.page',
    auditRisk: 'High - Missing active permit evidence'
  });
} else if (industry.toLowerCase().includes('therapist') && location.toLowerCase().includes('california')) {
  regulations.push({
    title: 'CA Board of Behavioral Sciences License Renewal',
    deadlineDays: 14,
    plainEnglish: 'Submit your continuing education units and renew your CA BBS license.',
    sourceUrl: 'https://www.bbs.ca.gov/',
    auditRisk: 'Medium - CEU certificates unverified'
  });
} else {
  regulations.push({
    title: 'General OSHA Annual Compliance & Safety Log',
    deadlineDays: 45,
    plainEnglish: 'Ensure your workplace safety logs are updated and reviewed.',
    sourceUrl: 'https://www.osha.gov/',
    auditRisk: 'Low'
  });
}

return { json: { email, industry, location, regulations } };

// Format the alert payload for Slack or Email notification
const data = $input.item.json;
const reg = data.regulations[0];

const slackMessage = `🚨 *RegCheck Alert for ${data.industry} in ${data.location}*\n\n` +
  `• *Requirement:* ${reg.title}\n` +
  `• *Plain English:* ${reg.plainEnglish}\n` +
  `• *Deadline:* In ${reg.deadlineDays} days\n` +
  `• *Source:* ${reg.sourceUrl}\n` +
  `• *Audit Risk:* ${reg.auditRisk}\n\n` +
  `_Action required: Upload confirmation email or renewal receipt to secure audit-ready status._`;

return { json: { email: data.email, slackText: slackMessage, regulation: reg } };
